// Initialize dashboard
setTimeout(function() {
    initializeDashboard();

    window.openTask = openTask;
    window.loadTasks = function() {
        const projectFilter = root_element.querySelector('#projectFilter');
        loadTasks(projectFilter ? projectFilter.value : '');
    };
    window.refreshDashboard = refreshDashboard;
    window.showNewTaskModal = showNewTaskModal;
    window.updateTaskProgress = updateTaskProgressFromForm;
    window.saveTask = saveTaskFromForm;
}, 1000);

