    font-size: 11px;
}

/* Tab Styling */
.dashboard-tabs {
    background: white;
    border-radius: 10px 10px 0 0;
    margin-bottom: 0;
}

.nav-tabs {
    border-bottom: 1px solid #dee2e6;
    padding: 0;
}

.nav-tabs .nav-item {
    margin-bottom: -1px;
}

.nav-tabs .nav-link {
    border: 1px solid transparent;
    border-top-left-radius: 10px;
    border-top-right-radius: 10px;
    color: #495057;
    font-weight: 500;
    padding: 12px 20px;
    transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out;
}

.nav-tabs .nav-link:hover {
    border-color: #e9ecef #e9ecef #dee2e6;
    color: #3498db;
}

.nav-tabs .nav-link.active {
    color: #3498db;
    background-color: #fff;
    border-color: #dee2e6 #dee2e6 #fff;
    font-weight: 600;
}

.nav-tabs .nav-link i {
    margin-right: 8px;
}

.tab-content {
    border: 1px solid #dee2e6;
    border-top: none;
    border-radius: 0 0 10px 10px;
    padding: 20px;
    background: white;
}

.tab-pane {
    display: none;
}

.tab-pane.active {
    display: block;
}

/* Modal styles */
.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.5);
    z-index: 1000;
    justify-content: center;
    align-items: center;
}

.modal.show {
    display: flex;
}

.modal-content {
    background: white;
    border-radius: 10px;
    width: 90%;
    max-width: 500px;
    max-height: 90vh;
    overflow-y: auto;
}

.modal-dialog.modal-lg .modal-content {
    max-width: 800px;
}

.modal-header {
    padding: 20px;
    border-bottom: 1px solid #e1e8ed;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.modal-header h5 {
    margin: 0;
    color: #2c3e50;
}

.modal-body {
    padding: 20px;
}

.modal-footer {
    padding: 20px;
    border-top: 1px solid #e1e8ed;
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.close {
    background: none;
    border: none;
    font-size: 24px;
    color: #7f8c8d;
    cursor: pointer;
    padding: 0;
}

.close:hover {
    color: #2c3e50;
}

.form-group {
    margin-bottom: 15px;
}

.form-group label {
    display: block;
    margin-bottom: 5px;
    color: #2c3e50;
    font-weight: 500;
}

.form-control {
    width: 100%;
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 5px;
    font-size: 14px;
}

.form-control-range {
    width: 100%;
    margin: 10px 0;
}

#progressValue, #updateProgressValue {
    display: inline-block;
    margin-left: 10px;
    font-weight: bold;
    color: #3498db;
}

.tender-details-view .row {
    margin-bottom: 15px;
}

.tender-details-view strong {
    color: #2c3e50;
    font-weight: 600;
}

.tender-item-modal {
    background: #f8f9fa;
    padding: 10px;
    border-radius: 6px;
    margin-bottom: 10px;
}

.tender-item-modal .row {
    display: flex;
    align-items: center;
    margin-bottom: 5px;
}

.tender-item-modal .col {
    padding: 5px;
}

.tender-item-modal .description {
    color: #2c3e50;
    font-weight: 500;
}

.tender-item-modal .employee {
    color: #7f8c8d;
    font-size: 13px;
}

.tender-item-modal .status {
    font-size: 12px;
    padding: 2px 8px;
    border-radius: 12px;
}

/* Date styling */
.parent-task-dates,
.child-task-dates,
.task-dates,
.tender-dates {
    margin-top: 8px;
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}

.parent-task-dates small,
.child-task-dates small,
.task-dates small,
.tender-dates small {
    color: #7f8c8d;
    font-size: 12px;
    display: flex;
    align-items: center;
    gap: 5px;
}

.parent-task-dates i,
.child-task-dates i,
.task-dates i,
.tender-dates i {
    font-size: 11px;
    opacity: 0.7;
}

/* Progress bar for tenders */
.progress-bar-tender {
    height: 6px;
    background: #e9ecef;
    border-radius: 3px;
    overflow: hidden;
}

.progress-fill-tender {
    height: 100%;
    border-radius: 3px;
    background: linear-gradient(90deg, #3498db, #2ecc71);
    transition: width 0.3s ease;
}

/* Responsive adjustments */
@media (max-width: 768px) {
    .dashboard-header {
        flex-direction: column;
        gap: 15px;
        text-align: center;
    }

    .project-filter, .tender-filter {
        flex-direction: column;
    }

    .parent-task-main {
        flex-direction: column;
        gap: 10px;
    }

    .parent-task-details {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .parent-task-progress {
        max-width: 100%;
        width: 100%;
    }

    .child-task-content {
        flex-direction: column;
    }

    .child-task-indicator {
        border-right: none;
        border-bottom: 2px solid #e1e8ed;
        padding-right: 0;
        padding-bottom: 10px;
        margin-right: 0;
        margin-bottom: 10px;
    }

    .child-task-body {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .child-task-progress {
        max-width: 100%;
        width: 100%;
    }

    .independent-task-body {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .independent-task-body .task-progress {
        max-width: 100%;
        width: 100%;
    }

    .tender-item-row {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .tender-item-progress {
        max-width: 100%;
        width: 100%;
    }

    .tender-header {
        flex-direction: column;
        gap: 10px;
    }

    .tender-status {
        align-self: flex-start;
    }

    .nav-tabs .nav-link {
        padding: 10px 15px;
        font-size: 14px;
    }

    .modal-content {
        width: 95%;
        margin: 10px;
    }

    .tender-item-modal .row {
        flex-direction: column;
        align-items: flex-start;
    }
}

@media (max-width: 576px) {
    .dashboard-stats {
        grid-template-columns: 1fr;
    }

    .parent-task-dates,
    .child-task-dates,
    .task-dates,
    .tender-dates {
        flex-direction: column;
        gap: 5px;
    }

    .parent-task-dates small,
    .child-task-dates small,
    .task-dates small,
    .tender-dates small {
        margin-left: 0 !important;
    }
}

.searchable-dropdown {
    position: relative;
    flex: 1;
}

.searchable-input {
    padding-right: 30px; 
}

.searchable-clear-btn {
    position: absolute;
    right: 8px;
    top: 50%;
    transform: translateY(-50%);
    background: none;
    border: none;
    font-size: 18px;
    line-height: 1;
    color: #95a5a6;
    cursor: pointer;
    padding: 2px 4px;
    z-index: 5;
}

.searchable-clear-btn:hover {
    color: #e74c3c;
}

script:
const PALETTE = ["#2490ef", "#2f9e44", "#f08c00", "#e03636", "#7048e8", "#0ca678", "#d6336c", "#1098ad", "#868e96", "#f59f00"];

function esc(v) {
    return frappe.utils.escape_html(v == null ? "" : String(v));
}

function q(sel) {
    return root_element.querySelector(sel);
}

function donut(items, size, fmt) {
    const show = (v) => (fmt ? fmt(v) : v);
    size = size || 150;
    const total = items.reduce((s, i) => s + i.value, 0);
    const r = size / 2 - 12, c = 2 * Math.PI * r;
    let offset = 0;
    const arcs = total ? items.map((it, idx) => {
        const len = (it.value / total) * c;
        const color = it.color || PALETTE[idx % PALETTE.length];
        const arc = `<circle r="${r}" cx="${size / 2}" cy="${size / 2}" fill="none" stroke="${color}" stroke-width="18"
            stroke-dasharray="${len} ${c - len}" stroke-dashoffset="${-offset}" transform="rotate(-90 ${size / 2} ${size / 2})"><title>${esc(it.label)}: ${esc(show(it.value))}</title></circle>`;
        offset += len;
        return arc;
    }).join("") : `<circle r="${r}" cx="${size / 2}" cy="${size / 2}" fill="none" stroke="#e9ecef" stroke-width="18"/>`;
    const list = items.map((it, idx) => `<div><span><i style="background:${it.color || PALETTE[idx % PALETTE.length]}"></i>${esc(it.label)}</span><b>${show(it.value)}</b></div>`).join("");
    return `<div class="donut-wrap"><svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">${arcs}
        <text x="50%" y="48%" text-anchor="middle" font-size="${fmt ? 13 : 22}" font-weight="700" fill="currentColor">${show(total)}</text>
        <text x="50%" y="62%" text-anchor="middle" font-size="11" fill="currentColor" opacity=".6">${__("Total")}</text></svg>
        <div class="donut-list">${list || `<div class="empty">${__("No data")}</div>`}</div></div>`;
}

function hbars(items, opts) {
    opts = opts || {};
    if (!items.length) return `<div class="empty">${__("No data")}</div>`;
    const max = Math.max(...items.map((i) => i.value), 1);
    return items.map((it, idx) => {
        const pct = (it.value / max) * 100;
        const color = it.color || opts.color || PALETTE[idx % PALETTE.length];
        return `<div class="hbar"><div class="hbar-head"><span class="hbar-name" title="${esc(it.label)}">${esc(it.label)}</span>
            <span class="hbar-val">${opts.format ? opts.format(it.value) : it.value}</span></div>
            <div class="track"><div class="fill" style="width:${pct}%;background:${color}"></div></div></div>`;
    }).join("");
}

function fill_select(sel, values, placeholder, current) {
    const el = q(sel);
    if (!el) return;
    el.innerHTML = `<option value="">${esc(placeholder)}</option>` + values.map((v) => {
        const value = typeof v === "string" ? v : v.value;
        const label = typeof v === "string" ? v : v.label;
        return `<option value="${esc(value)}" ${value === current ? "selected" : ""}>${esc(label)}</option>`;
    }).join("");
}

const state = { company: "", status: "Open", project: "", currency: null };

function money(v) {
    return format_currency(flt(v), state.currency || frappe.defaults.get_default("currency"), 0);
}

function status_pill(status) {
    const map = { "Within Budget": "green", "Warning": "orange", "Exceeded": "red", "Open": "blue", "Completed": "green", "Cancelled": "gray" };
    return status ? `<span class="pill ${map[status] || "gray"}">${esc(__(status))}</span>` : `<span class="pill gray">${__("No Budget")}</span>`;
}

function util_color(pct) {
    return pct > 100 ? "#e03636" : pct >= 90 ? "#f08c00" : "#2f9e44";
}

function kpi(label, value, note, accent, route) {
    return `<div class="kpi ${route ? "clickable" : ""}" style="--accent:${accent || "#2490ef"}" ${route ? `data-route='${esc(JSON.stringify(route))}'` : ""}>
        <div class="kpi-label">${label}</div><div class="kpi-value" title="${esc(value)}">${value}</div>${note ? `<div class="kpi-note">${note}</div>` : ""}</div>`;
}

function load_filters() {
    frappe.call({
        method: "altor_project.api.dashboard.get_filter_options",
        callback(r) {
            const o = r.message || {};
            fill_select("#poCompany", o.companies || [], __("All Companies"), state.company);
            fill_select("#poProject", (o.projects || []).map((p) => ({ value: p.name, label: p.project_name && p.project_name !== p.name ? `${p.name}: ${p.project_name}` : p.name })), __("All Projects"), state.project);
        }
    });
}

function load() {
    q("#poBody").innerHTML = `<div class="loading">${__("Loading project overview...")}</div>`;
    frappe.call({
        method: "altor_project.api.dashboard.get_project_overview",
        args: { filters: { company: state.company, status: state.status, project: state.project } },
        callback(r) { render(r.message || {}); },
        error() { q("#poBody").innerHTML = `<div class="empty">${__("Could not load the dashboard.")}</div>`; }
    });
}

function render(data) {
    state.currency = data.currency;
    const s = data.summary || {};
    const projects = data.projects || [];

    const kpis1 = [
        kpi(__("Projects"), s.total || 0, `${s.open || 0} ${__("open")} · ${s.completed || 0} ${__("completed")}`, "#2490ef", ["List", "Project", "List"]),
        kpi(__("Overdue"), s.overdue || 0, __("Open projects past end date"), s.overdue ? "#e03636" : "#2f9e44"),
        kpi(__("Due in 30 Days"), s.due_soon || 0, __("Open projects ending soon"), "#f08c00"),
        kpi(__("Avg Progress"), `${s.avg_progress || 0}%`, __("Open projects"), "#7048e8"),
        kpi(__("Workers on Site Today"), s.workers_today || 0, `${__("This month")} ${money(s.manpower_this_month)}`, "#d6336c", ["query-report", "Manpower Cost Summary"]),
        kpi(__("Open Tasks"), s.open_tasks || 0, `${s.overdue_tasks || 0} ${__("overdue")}`, s.overdue_tasks ? "#e03636" : "#0ca678", ["List", "Task", "List"]),
    ].join("");
    const util = flt(s.utilization);
    const kpis2 = [
        kpi(__("Contract Value"), money(s.contract_value), `${__("Billed")} ${money(s.billed)}`, "#1098ad"),
        kpi(__("Total Budget"), money(s.budget), __("Submitted project budgets"), "#2490ef", ["List", "Project Budget", "List"]),
        kpi(__("Committed"), money(s.committed), __("Purchase & subcontract orders"), "#7048e8"),
        kpi(__("Actual"), money(s.actual), __("Purchase & subcontract invoices"), "#0ca678"),
        kpi(__("Manpower Cost"), money(s.manpower), `${__("Outsourced")} ${money(s.manpower_outsourced)}`, "#d6336c", ["List", "Manpower Entry", "List"]),
        kpi(__("Balance"), money(s.balance), `${__("Utilized")} ${money(s.utilized)}`, flt(s.balance) < 0 ? "#e03636" : "#2f9e44"),
        kpi(__("Budget Utilization"), `${util}%`, `${s.over_budget || 0} ${__("over")} · ${s.at_risk || 0} ${__("at risk")}`, util_color(util)),
    ].join("");

    let alerts = "";
    if (s.over_budget) alerts += `<div class="alert red"><b>${s.over_budget}</b> ${__("project(s) have exceeded their budget.")}</div>`;
    if (s.at_risk) alerts += `<div class="alert orange"><b>${s.at_risk}</b> ${__("project(s) have reached their budget warning threshold.")}</div>`;
    if (s.without_budget) alerts += `<div class="alert orange"><b>${s.without_budget}</b> ${__("open project(s) have no submitted Project Budget.")}</div>`;
    if (s.overdue) alerts += `<div class="alert red"><b>${s.overdue}</b> ${__("open project(s) are past their expected end date.")}</div>`;

    // status donut
    const status_colors = { Open: "#2490ef", Completed: "#2f9e44", Cancelled: "#868e96" };
    const status_items = Object.entries(data.status_counts || {}).map(([k, v]) => ({ label: __(k), value: v, color: status_colors[k] }));

    // budget vs utilized per project (top 10 by budget)
    const budgeted = projects.filter((p) => p.budget).sort((a, b) => b.budget - a.budget).slice(0, 10);
    const proj_bars = budgeted.length ? budgeted.map((p) => {
        const pct = p.budget ? Math.min((p.utilized / p.budget) * 100, 100) : 0;
        const actual_pct = p.budget ? Math.min((p.actual / p.budget) * 100, 100) : 0;
        return `<div class="hbar link-project" data-name="${esc(p.name)}" style="cursor:pointer">
            <div class="hbar-head"><span class="hbar-name" title="${esc(p.project_name)}">${esc(p.project_name || p.name)}</span>
            <span class="hbar-val">${money(p.utilized)} / ${money(p.budget)} · <b style="color:${util_color(p.utilization)}">${flt(p.utilization).toFixed(1)}%</b></span></div>
            <div class="track"><div class="fill ghost" style="width:${pct}%;background:${util_color(p.utilization)}"></div>
            <div class="fill" style="width:${actual_pct}%;background:${util_color(p.utilization)}"></div></div></div>`;
    }).join("") + `<div class="legend"><span><i style="background:#2f9e44"></i>${__("Actual (invoiced)")}</span><span><i style="background:#2f9e44;opacity:.35"></i>${__("Utilized incl. open orders")}</span></div>`
        : `<div class="empty">${__("No submitted Project Budgets yet.")}</div>`;

    // manpower: split + top projects
    const mp_projects = projects.filter((p) => p.manpower).sort((a, b) => b.manpower - a.manpower).slice(0, 6);
    const manpower_html = flt(s.manpower)
        ? donut([
            { label: __("Own Staff"), value: Math.round(flt(s.manpower_own)), color: "#2490ef" },
            { label: __("Outsourced"), value: Math.round(flt(s.manpower_outsourced)), color: "#f08c00" }
        ], 130, money) + hbars(mp_projects.map((p) => ({ label: p.project_name || p.name, value: p.manpower })), { color: "#d6336c", format: money })
        : `<div class="empty">${__("No Manpower Entries yet.")}</div>`;

    // item group breakdown
    const groups = data.item_groups || [];
    const group_rows = groups.map((g) => {
        const pct = flt(g.utilization);
        const st = pct > 100 ? "Exceeded" : pct >= 90 ? "Warning" : "Within Budget";
        return `<tr>
            <td><b>${esc(g.item_group)}</b><div class="muted">${g.projects} ${__("project(s)")}</div></td>
            <td class="num">${money(g.budget)}</td>
            <td class="num">${money(g.committed)}</td>
            <td class="num">${money(g.actual)}</td>
            <td class="num">${money(g.utilized)}</td>
            <td class="num" style="color:${g.balance < 0 ? "#e03636" : "inherit"}">${money(g.balance)}</td>
            <td style="min-width:150px"><span class="mini-progress"><span style="width:${Math.min(pct, 100)}%;background:${util_color(pct)}"></span></span>${pct.toFixed(1)}%</td>
            <td>${status_pill(st)}</td></tr>`;
    }).join("");

    // budget alerts per project + item group
    const alert_rows = (data.alerts || []).map((a) => `<tr class="link" data-budget="${esc(a.budget_name)}">
        <td>${esc(a.project)}</td><td><b>${esc(a.item_group)}</b></td>
        <td class="num">${money(a.budget)}</td><td class="num">${money(a.utilized)}</td>
        <td class="num" style="color:${a.balance < 0 ? "#e03636" : "inherit"}">${money(a.balance)}</td>
        <td class="num"><b style="color:${util_color(a.utilization)}">${flt(a.utilization).toFixed(1)}%</b></td><td>${status_pill(a.status)}</td></tr>`).join("");

    // projects table
    const project_rows = projects.map((p) => `<tr class="link" data-name="${esc(p.name)}">
        <td><b>${esc(p.name)}</b><div class="muted">${esc(p.project_name || "")}</div></td>
        <td>${esc(p.customer || "")}</td>
        <td>${status_pill(p.status)}</td>
        <td style="min-width:140px"><span class="mini-progress"><span style="width:${Math.min(p.percent_complete, 100)}%"></span></span>${flt(p.percent_complete).toFixed(0)}%</td>
        <td>${p.expected_end_date ? esc(frappe.datetime.str_to_user(p.expected_end_date)) : "-"}
            ${p.overdue ? ` <span class="pill red">${__("Overdue")}</span>` : p.due_soon ? ` <span class="pill orange">${__("Due soon")}</span>` : ""}</td>
        <td class="num">${money(p.contract_value)}</td>
        <td class="num">${p.budget ? money(p.budget) : "-"}</td>
        <td class="num">${p.budget ? money(p.utilized) : "-"}</td>
        <td class="num">${p.budget ? `<b style="color:${util_color(p.utilization)}">${flt(p.utilization).toFixed(1)}%</b>` : "-"}</td>
        <td>${p.budget_name ? status_pill(p.budget_status) : status_pill("")}</td>
        <td class="num">${p.manpower ? money(p.manpower) : "-"}${p.workers_today ? `<div class="muted">${p.workers_today} ${__("today")}</div>` : ""}</td>
        <td class="num">${(p.tasks && p.tasks.open) || 0}${p.tasks && p.tasks.overdue ? ` <span class="pill red">${p.tasks.overdue} ${__("late")}</span>` : ""}</td>
    </tr>`).join("");

    q("#poBody").innerHTML = `
        <div class="kpis">${kpis1}</div>
        <div class="kpis">${kpis2}</div>
        ${alerts}
        <div class="grid">
            <div class="panel"><h4>${__("Projects by Status")}</h4>${donut(status_items)}</div>
            <div class="panel"><h4>${__("Manpower Cost")} <small>${__("Own staff vs outsourced")}</small></h4>${manpower_html}</div>
            <div class="panel"><h4>${__("Budget vs Utilized")} <small>${__("Top 10 by budget")}</small></h4>${proj_bars}</div>
        </div>
        <div class="grid">
            <div class="panel wide"><h4>${__("Item Group Wise Budget")} <small>${__("All selected projects")}</small></h4>
                ${groups.length ? `<div class="table-wrap"><table class="t"><thead><tr><th>${__("Item Group")}</th><th class="num">${__("Budget")}</th><th class="num">${__("Committed")}</th><th class="num">${__("Actual")}</th><th class="num">${__("Utilized")}</th><th class="num">${__("Balance")}</th><th>${__("Utilization")}</th><th>${__("Status")}</th></tr></thead><tbody>${group_rows}</tbody></table></div>` : `<div class="empty">${__("No item group budgets found.")}</div>`}
            </div>
        </div>
        <div class="grid">
            <div class="panel wide"><h4>${__("Budget Warnings")} <small>${__("Item groups over budget or past the warning threshold")}</small></h4>
                ${alert_rows ? `<div class="table-wrap"><table class="t"><thead><tr><th>${__("Project")}</th><th>${__("Item Group")}</th><th class="num">${__("Budget")}</th><th class="num">${__("Utilized")}</th><th class="num">${__("Balance")}</th><th class="num">${__("Used %")}</th><th>${__("Status")}</th></tr></thead><tbody>${alert_rows}</tbody></table></div>` : `<div class="alert green">${__("All item groups are within budget.")}</div>`}
            </div>
        </div>
        <div class="grid">
            <div class="panel wide"><h4>${__("Projects")} <small>${projects.length} ${__("shown")}</small></h4>
                ${projects.length ? `<div class="table-wrap"><table class="t"><thead><tr><th>${__("Project")}</th><th>${__("Customer")}</th><th>${__("Status")}</th><th>${__("Progress")}</th><th>${__("End Date")}</th><th class="num">${__("Contract")}</th><th class="num">${__("Budget")}</th><th class="num">${__("Utilized")}</th><th class="num">${__("Used %")}</th><th>${__("Budget Status")}</th><th class="num">${__("Manpower")}</th><th class="num">${__("Open Tasks")}</th></tr></thead><tbody>${project_rows}</tbody></table></div>` : `<div class="empty">${__("No projects match the filters.")}</div>`}
            </div>
        </div>`;

    root_element.querySelectorAll("tr[data-name], .link-project").forEach((el) => {
        el.addEventListener("click", () => frappe.set_route("Form", "Project", el.dataset.name));
    });
    root_element.querySelectorAll("tr[data-budget]").forEach((el) => {
        el.addEventListener("click", () => frappe.set_route("Form", "Project Budget", el.dataset.budget));
    });
    root_element.querySelectorAll(".kpi[data-route]").forEach((el) => {
        el.addEventListener("click", () => frappe.set_route(...JSON.parse(el.dataset.route)));
    });
}

q("#poCompany").addEventListener("change", (e) => { state.company = e.target.value; load(); });
q("#poStatus").addEventListener("change", (e) => { state.status = e.target.value; load(); });
q("#poProject").addEventListener("change", (e) => { state.project = e.target.value; load(); });
q("#poRefresh").addEventListener("click", () => load());

load_filters();
load();

