script:
const PALETTE = ["#2490ef", "#2f9e44", "#f08c00", "#e03636", "#7048e8", "#0ca678", "#d6336c", "#1098ad", "#868e96", "#f59f00"];

function esc(v) {
    return frappe.utils.escape_html(v == null ? "" : String(v));
}

function q(sel) {
    return root_element.querySelector(sel);
}

function donut(items, size, fmt) {
    const show = (v) => (fmt ? fmt(v) : v);
    size = size || 150;
    const total = items.reduce((s, i) => s + i.value, 0);
    const r = size / 2 - 12, c = 2 * Math.PI * r;
    let offset = 0;
    const arcs = total ? items.map((it, idx) => {
        const len = (it.value / total) * c;
        const color = it.color || PALETTE[idx % PALETTE.length];
        const arc = `<circle r="${r}" cx="${size / 2}" cy="${size / 2}" fill="none" stroke="${color}" stroke-width="18"
            stroke-dasharray="${len} ${c - len}" stroke-dashoffset="${-offset}" transform="rotate(-90 ${size / 2} ${size / 2})"><title>${esc(it.label)}: ${esc(show(it.value))}</title></circle>`;
        offset += len;
        return arc;
    }).join("") : `<circle r="${r}" cx="${size / 2}" cy="${size / 2}" fill="none" stroke="#e9ecef" stroke-width="18"/>`;
    const list = items.map((it, idx) => `<div><span><i style="background:${it.color || PALETTE[idx % PALETTE.length]}"></i>${esc(it.label)}</span><b>${show(it.value)}</b></div>`).join("");
    return `<div class="donut-wrap"><svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">${arcs}
        <text x="50%" y="48%" text-anchor="middle" font-size="${fmt ? 13 : 22}" font-weight="700" fill="currentColor">${show(total)}</text>
        <text x="50%" y="62%" text-anchor="middle" font-size="11" fill="currentColor" opacity=".6">${__("Total")}</text></svg>
        <div class="donut-list">${list || `<div class="empty">${__("No data")}</div>`}</div></div>`;
}

function hbars(items, opts) {
    opts = opts || {};
    if (!items.length) return `<div class="empty">${__("No data")}</div>`;
    const max = Math.max(...items.map((i) => i.value), 1);
    return items.map((it, idx) => {
        const pct = (it.value / max) * 100;
        const color = it.color || opts.color || PALETTE[idx % PALETTE.length];
        return `<div class="hbar"><div class="hbar-head"><span class="hbar-name" title="${esc(it.label)}">${esc(it.label)}</span>
            <span class="hbar-val">${opts.format ? opts.format(it.value) : it.value}</span></div>
            <div class="track"><div class="fill" style="width:${pct}%;background:${color}"></div></div></div>`;
    }).join("");
}

function fill_select(sel, values, placeholder, current) {
    const el = q(sel);
    if (!el) return;
    el.innerHTML = `<option value="">${esc(placeholder)}</option>` + values.map((v) => {
        const value = typeof v === "string" ? v : v.value;
        const label = typeof v === "string" ? v : v.label;
        return `<option value="${esc(value)}" ${value === current ? "selected" : ""}>${esc(label)}</option>`;
    }).join("");
}

const state = { company: "", department: "", currency: null };

function money(v) {
    return format_currency(flt(v), state.currency || frappe.defaults.get_default("currency"), 0);
}

function kpi(label, value, note, accent, route) {
    return `<div class="kpi ${route ? "clickable" : ""}" style="--accent:${accent || "#2490ef"}" ${route ? `data-route='${esc(JSON.stringify(route))}'` : ""}>
        <div class="kpi-label">${label}</div><div class="kpi-value">${value}</div>${note ? `<div class="kpi-note">${note}</div>` : ""}</div>`;
}

function date_str(d) {
    return d ? esc(frappe.datetime.str_to_user(d)) : "";
}

function in_days(n) {
    if (n === 0) return `<span class="pill green">${__("Today")}</span>`;
    if (n === 1) return `<span class="pill blue">${__("Tomorrow")}</span>`;
    if (n < 0) return `<span class="pill red">${__("{0} days ago", [-n])}</span>`;
    return `<span class="pill gray">${__("in {0} days", [n])}</span>`;
}

function list(items, row_fn, empty_text) {
    if (!items || !items.length) return `<div class="empty">${empty_text || __("Nothing to show")}</div>`;
    return items.map(row_fn).join("");
}

function load_filters() {
    frappe.call({
        method: "altor_project.api.dashboard.get_filter_options",
        callback(r) {
            const o = r.message || {};
            fill_select("#hrCompany", o.companies || [], __("All Companies"), state.company);
            fill_select("#hrDepartment", o.departments || [], __("All Departments"), state.department);
        }
    });
}

function load() {
    q("#hrBody").innerHTML = `<div class="loading">${__("Loading HR dashboard...")}</div>`;
    frappe.call({
        method: "altor_project.api.dashboard.get_hr_overview",
        args: { filters: { company: state.company, department: state.department } },
        callback(r) { render(r.message || {}); },
        error() { q("#hrBody").innerHTML = `<div class="empty">${__("Could not load the dashboard.")}</div>`; }
    });
}

function render(d) {
    const s = d.summary || {};
    state.currency = d.currency;
    const today = frappe.datetime.get_today();
    q("#hrToday").textContent = __("Today: {0}", [frappe.datetime.str_to_user(today)]);

    const kpis1 = [
        kpi(__("Active Employees"), s.total_active || 0, `${s.own_staff || 0} ${__("own")} · ${s.outsourced || 0} ${__("outsourced")}`, "#2490ef", ["List", "Employee", "List"]),
        kpi(__("Present Today"), (s.present_today || 0) + (s.wfh_today || 0), s.attendance_marked ? `${s.wfh_today || 0} ${__("WFH")} · ${s.half_day_today || 0} ${__("half day")}` : __("Attendance not marked yet"), "#2f9e44", ["List", "Attendance", "List"]),
        kpi(__("On Leave Today"), s.on_leave_today || 0, __("Approved leave"), "#f08c00"),
        kpi(__("Absent Today"), s.absent_today || 0, s.attendance_marked ? `${s.not_marked_today || 0} ${__("not marked")}` : "", s.absent_today ? "#e03636" : "#868e96"),
        kpi(__("Checked In Today"), s.checked_in_today || 0, __("From Employee Checkin"), "#0ca678", ["List", "Employee Checkin", "List"]),
    ].join("");
    const kpis2 = [
        kpi(__("Pending Leave Requests"), s.pending_leaves || 0, __("Waiting for approval"), s.pending_leaves ? "#f08c00" : "#2f9e44", ["List", "Leave Application", "List"]),
        kpi(__("Joined This Month"), s.joiners_this_month || 0, "", "#7048e8"),
        kpi(__("Left This Month"), s.exits_this_month || 0, "", s.exits_this_month ? "#e03636" : "#868e96"),
        kpi(__("Workers on Site Today"), s.manpower_today || 0, __("From Manpower Entries"), "#d6336c", ["List", "Manpower Entry", "List"]),
        kpi(__("Manpower Cost (Month)"), money(s.manpower_cost_month), `${__("Outsourced")} ${money(s.manpower_outsourced_month)}`, "#d6336c", ["query-report", "Manpower Cost Summary"]),
    ].join("");

    // attendance trend: stacked columns
    const trend = d.attendance_trend || [];
    const tmax = Math.max(...trend.map((t) => t.present + t.half_day + t.absent + t.on_leave), 1);
    const seg = (v, color, label) => v ? `<div style="height:${(v / tmax) * 120}px;background:${color}" title="${label}: ${v}"></div>` : "";
    const trend_html = trend.length ? `<div class="cols">${trend.map((t) => `
        <div class="col"><div class="col-stack">${seg(t.present, "#2f9e44", __("Present"))}${seg(t.half_day, "#74b816", __("Half Day"))}${seg(t.on_leave, "#f08c00", __("On Leave"))}${seg(t.absent, "#e03636", __("Absent"))}</div>
        <div class="col-label">${esc(moment(t.date).format("ddd D"))}</div></div>`).join("")}</div>
        <div class="legend"><span><i style="background:#2f9e44"></i>${__("Present")}</span><span><i style="background:#74b816"></i>${__("Half Day")}</span><span><i style="background:#f08c00"></i>${__("On Leave")}</span><span><i style="background:#e03636"></i>${__("Absent")}</span></div>`
        : `<div class="empty">${__("No attendance records")}</div>`;

    const by_gender = (d.by_gender || []).map((g) => ({ label: __(g.label), value: g.value }));
    const by_type = (d.by_employment_type || []).map((g) => ({ label: __(g.label), value: g.value }));

    const leave_row = (l) => `<div class="list-row"><span><b>${esc(l.employee_name)}</b> <span class="muted">${esc(l.leave_type)}</span></span>
        <span class="muted">${date_str(l.from_date)} – ${date_str(l.to_date)}</span></div>`;
    const pending_row = (l) => `<div class="list-row link-leave" data-name="${esc(l.name)}" style="cursor:pointer"><span><b>${esc(l.employee_name)}</b> <span class="muted">${esc(l.leave_type)} · ${flt(l.total_leave_days)} ${__("day(s)")}</span></span>
        <span class="muted">${date_str(l.from_date)} – ${date_str(l.to_date)}</span></div>`;
    const bday_row = (b) => `<div class="list-row"><span><b>${esc(b.employee_name)}</b> <span class="muted">${esc(b.department || "")}</span></span><span>${date_str(b.date)} ${in_days(b.days)}</span></div>`;
    const anniv_row = (a) => `<div class="list-row"><span><b>${esc(a.employee_name)}</b> <span class="muted">${a.years} ${__("year(s)")}</span></span><span>${date_str(a.date)} ${in_days(a.days)}</span></div>`;
    const doc_row = (x) => `<div class="list-row link-emp" data-name="${esc(x.employee)}" style="cursor:pointer"><span><b>${esc(x.employee_name)}</b> <span class="muted">${esc(x.document)} ${esc(x.number || "")}</span></span><span>${date_str(x.date)} ${x.days < 0 ? `<span class="pill red">${__("Expired")}</span>` : in_days(x.days)}</span></div>`;
    const joiner_row = (j) => `<div class="list-row link-emp" data-name="${esc(j.employee)}" style="cursor:pointer"><span><b>${esc(j.employee_name)}</b> <span class="muted">${esc(j.designation || "")} ${j.department ? "· " + esc(j.department) : ""}</span></span><span class="muted">${date_str(j.date_of_joining)}</span></div>`;

    let alerts = "";
    const expired = (d.expiring_documents || []).filter((x) => x.days < 0).length;
    if (expired) alerts += `<div class="alert red"><b>${expired}</b> ${__("employee document(s) have expired.")}</div>`;
    if (s.pending_leaves) alerts += `<div class="alert orange"><b>${s.pending_leaves}</b> ${__("leave application(s) are waiting for approval.")}</div>`;

    q("#hrBody").innerHTML = `
        <div class="kpis">${kpis1}</div>
        <div class="kpis">${kpis2}</div>
        ${alerts}
        <div class="grid">
            <div class="panel"><h4>${__("Attendance")} <small>${__("Last 7 days")}</small></h4>${trend_html}</div>
            <div class="panel"><h4>${__("Headcount by Department")}</h4>${hbars(d.by_department || [])}</div>
        </div>
        <div class="grid">
            <div class="panel"><h4>${__("Gender")}</h4>${donut(by_gender)}</div>
            <div class="panel"><h4>${__("Employment Type")}</h4>${donut(by_type)}</div>
            <div class="panel"><h4>${__("Top Designations")}</h4>${hbars(d.by_designation || [], { color: "#7048e8" })}</div>
        </div>
        <div class="grid">
            <div class="panel"><h4>${__("Outsourced Manpower")} <small>${s.outsourced || 0} ${__("workers")}</small></h4>
                ${(d.by_agency || []).length ? hbars(d.by_agency, { color: "#f08c00", format: (v) => `${v} ${__("workers")}` }) : `<div class="empty">${__("No outsourced workers. Tick Outsourced Manpower on the Employee.")}</div>`}</div>
            <div class="panel"><h4>${__("Manpower Cost by Project")} <small>${__("This month")}</small></h4>${hbars(d.manpower_by_project || [], { color: "#d6336c", format: money })}</div>
            <div class="panel"><h4>${__("Agency Cost")} <small>${__("This month")}</small></h4>${hbars(d.manpower_cost_by_agency || [], { color: "#f08c00", format: money })}</div>
        </div>
        <div class="grid">
            <div class="panel"><h4>${__("On Leave Today")} <small>${(d.leaves_today || []).length}</small></h4>${list(d.leaves_today, leave_row, __("No one is on leave today"))}</div>
            <div class="panel"><h4>${__("Pending Leave Applications")} <small>${s.pending_leaves || 0}</small></h4>${list(d.pending_leaves, pending_row, __("No pending applications"))}</div>
        </div>
        <div class="grid">
            <div class="panel"><h4>${__("Upcoming Birthdays")} <small>${__("Next 30 days")}</small></h4>${list(d.birthdays, bday_row, __("No birthdays in the next 30 days"))}</div>
            <div class="panel"><h4>${__("Work Anniversaries")} <small>${__("Next 30 days")}</small></h4>${list(d.anniversaries, anniv_row, __("No anniversaries in the next 30 days"))}</div>
        </div>
        <div class="grid">
            <div class="panel"><h4>${__("Passports Expiring")} <small>${__("Next 60 days")}</small></h4>${list(d.expiring_documents, doc_row, __("No passports expiring soon"))}</div>
            <div class="panel"><h4>${__("New Joiners")} <small>${__("This month")}</small></h4>${list(d.new_joiners, joiner_row, __("No new joiners this month"))}</div>
        </div>`;

    root_element.querySelectorAll(".link-emp").forEach((el) => el.addEventListener("click", () => frappe.set_route("Form", "Employee", el.dataset.name)));
    root_element.querySelectorAll(".link-leave").forEach((el) => el.addEventListener("click", () => frappe.set_route("Form", "Leave Application", el.dataset.name)));
    root_element.querySelectorAll(".kpi[data-route]").forEach((el) => el.addEventListener("click", () => frappe.set_route(...JSON.parse(el.dataset.route))));
}

q("#hrCompany").addEventListener("change", (e) => { state.company = e.target.value; load(); });
q("#hrDepartment").addEventListener("change", (e) => { state.department = e.target.value; load(); });
q("#hrRefresh").addEventListener("click", () => load());

load_filters();
load();

