.dash-title { font-size: 20px; font-weight: 700; margin: 0; }
.dash-sub { font-size: 12px; color: var(--text-muted, #6c7680); margin-top: 2px; }
.dash-filters { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.dash-filters select, .dash-filters button { height: 32px; border-radius: 6px; border: 1px solid var(--border-color, #d1d8dd); background: var(--control-bg, #f4f5f6); color: var(--text-color, #1f272e); padding: 0 10px; font-size: 13px; max-width: 220px; }
.dash-filters button { background: var(--primary, #2490ef); color: #fff; border-color: transparent; cursor: pointer; font-weight: 600; }
.kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 12px; }
.kpi { background: var(--card-bg, #fff); border: 1px solid var(--border-color, #e2e6e9); border-radius: 10px; padding: 12px 14px; position: relative; overflow: hidden; }
.kpi::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 4px; background: var(--accent, #2490ef); }
.kpi-label { font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: var(--text-muted, #6c7680); }
.kpi-value { font-size: 20px; font-weight: 700; margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.kpi-note { font-size: 11.5px; color: var(--text-muted, #6c7680); margin-top: 2px; }
.kpi.clickable { cursor: pointer; }
.kpi.clickable:hover { border-color: var(--accent, #2490ef); }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 12px; margin-bottom: 12px; }
.panel { background: var(--card-bg, #fff); border: 1px solid var(--border-color, #e2e6e9); border-radius: 10px; padding: 14px 16px; min-width: 0; }
.panel.wide { grid-column: 1 / -1; }
.panel h4 { margin: 0 0 10px; font-size: 14px; font-weight: 700; display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.panel h4 small { font-weight: 400; color: var(--text-muted, #6c7680); font-size: 12px; }
.empty { color: var(--text-muted, #6c7680); font-size: 13px; padding: 12px 0; text-align: center; }
.hbar { margin: 8px 0; font-size: 12.5px; }
.hbar-head { display: flex; justify-content: space-between; gap: 8px; }
.hbar-name { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.hbar-val { color: var(--text-muted, #6c7680); white-space: nowrap; }
.track { position: relative; height: 9px; background: var(--subtle-fg, #eef0f2); border-radius: 5px; margin-top: 4px; overflow: hidden; }
.fill { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 5px; }
.fill.ghost { opacity: .35; }
.legend { display: flex; flex-wrap: wrap; gap: 10px; font-size: 12px; color: var(--text-muted, #6c7680); margin-top: 8px; }
.legend i { display: inline-block; width: 10px; height: 10px; border-radius: 2px; margin-right: 4px; vertical-align: -1px; }
.donut-wrap { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; }
.donut-wrap svg { flex: 0 0 auto; }
.donut-list { flex: 1; min-width: 140px; font-size: 13px; }
.donut-list div { display: flex; justify-content: space-between; gap: 8px; padding: 3px 0; }
.donut-list i { display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: 6px; }
.table-wrap { overflow-x: auto; }
table.t { width: 100%; border-collapse: collapse; font-size: 12.5px; }
table.t th { text-align: left; font-weight: 600; color: var(--text-muted, #6c7680); border-bottom: 1px solid var(--border-color, #e2e6e9); padding: 7px 8px; white-space: nowrap; }
table.t td { border-bottom: 1px solid var(--border-color, #eef0f2); padding: 7px 8px; vertical-align: middle; }
table.t tr:last-child td { border-bottom: none; }
table.t td.num, table.t th.num { text-align: right; white-space: nowrap; }
table.t tr.link { cursor: pointer; }
table.t tr.link:hover td { background: var(--subtle-accent, #f4f5f6); }
.pill { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 600; white-space: nowrap; }
.pill.green { background: rgba(47,158,68,.14); color: #2b8a3e; }
.pill.orange { background: rgba(240,140,0,.16); color: #c06500; }
.pill.red { background: rgba(224,54,54,.14); color: #c92a2a; }
.pill.blue { background: rgba(36,144,239,.14); color: #1971c2; }
.pill.gray { background: rgba(108,118,128,.14); color: #5c6670; }
.mini-progress { width: 90px; height: 6px; border-radius: 3px; background: var(--subtle-fg, #eef0f2); display: inline-block; vertical-align: middle; overflow: hidden; margin-right: 6px; }
.mini-progress span { display: block; height: 100%; background: #2490ef; }
.alert { border-radius: 8px; padding: 9px 12px; margin-bottom: 10px; font-size: 13px; display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.alert.red { background: rgba(224,54,54,.10); color: #c92a2a; }
.alert.orange { background: rgba(240,140,0,.12); color: #b35c00; }
.alert.green { background: rgba(47,158,68,.10); color: #2b8a3e; }
.loading { padding: 40px; text-align: center; color: var(--text-muted, #6c7680); }
.cols { display: flex; align-items: flex-end; gap: 6px; height: 150px; padding-top: 8px; }
.col { flex: 1; display: flex; flex-direction: column; justify-content: flex-end; align-items: stretch; height: 100%; min-width: 0; }
.col-stack { display: flex; flex-direction: column-reverse; border-radius: 4px 4px 0 0; overflow: hidden; }
.col-label { font-size: 10.5px; text-align: center; color: var(--text-muted, #6c7680); margin-top: 4px; white-space: nowrap; }
.list-row { display: flex; justify-content: space-between; gap: 8px; padding: 6px 0; border-bottom: 1px dashed var(--border-color, #e2e6e9); font-size: 12.5px; }
.list-row:last-child { border-bottom: none; }
.list-row b { font-weight: 600; }
.muted { color: var(--text-muted, #6c7680); }
@media (max-width: 600px) { .grid { grid-template-columns: 1fr; } .kpi-value { font-size: 17px; } }
